INSERT IGNORE INTO `tea_topic` VALUES (1,'#春茶品鉴','春日游，杏花吹满头。在这个万物复苏的季节，一起来分享你的第一口春茶吧。',125000,342,1,'2026-04-27 17:49:33','春茶品鉴','2026-04-29 08:56:58'),(2,'#紫砂壶','泥绘春秋，壶中日月。紫砂壶的养护、鉴赏与交流。',82000,156,1,'2026-04-27 17:49:33','紫砂壶','2026-04-29 08:56:58'),(3,'#茶山游','寻味山野，探访名山名枞。分享你的茶山行记与见闻。',45000,89,0,'2026-04-27 17:49:33','茶山游','2026-04-29 08:56:58'),(4,'#明前龙井','明前茶，贵如金。西湖龙井的核心产区探秘与品鉴心得。',158003,512,1,'2026-04-27 17:49:33','明前龙井','2026-05-14 08:13:11'),(5,'#武夷岩茶','岩骨花香，半壁江山。肉桂、水仙、大红袍的冲泡与品鉴。',67001,120,0,'2026-04-27 17:49:33','武夷岩茶','2026-04-29 09:37:16');
